468	export type Field =
469	  | 'evidence' | 'headline' | 'option_action' | 'option_to' | 'supplier_name' | 'kind'
470	  | 'hours_left' | 'waiting_hours' | 'has_reply' | 'reply_after_launch' | 'silent_hours'
471	export type Channel = 'phone' | 'teams' | 'both'
472	/** What a routine looks at on each check. Missing means open decisions. */
473	export type Trigger = 'decisions' | 'waiting' | 'replies' | 'shipments'
474	/** How much a routine may do on its own. Missing means "tell". */
475	export type Mode = 'ask' | 'tell' | 'quiet'
476	export type StepKind = 'carry_out' | 'notify' | 'log' | 'chase' | 'call' | 'ask_status'
477	
478	export interface Cond {
479	  id: string; field: Field; op: 'contains' | 'is' | 'any_of' | 'lt' | 'gt'; value: string | number | boolean; text: string
480	}
481	export interface Step {
482	  id: string
483	  do: StepKind
484	  text: string
485	  match?: { to?: string; action_contains?: string }
486	  channel?: Channel
487	  message?: string
488	}
489	export interface Spec { on?: Trigger; when: Cond[]; then: Step[] }
490	
491	export interface Did {
492	  do: StepKind
493	  card?: string; shipment?: string; option?: string; text?: string; channel?: Channel; status?: string; dry?: boolean
494	  /** Set on a real run: the recorded action, for Undo. */
495	  action_id?: string | null
496	  /** Set in "ask me" mode: the proposal waiting for an OK instead of the action. */
497	  proposed?: string
498	}
499	export interface Run { at: string; ok: boolean; dry?: boolean; result?: unknown; error?: string; log?: string[]; did?: Did[] }
500	export interface Routine {
501	  id: string; name: string; description: string; spec?: Spec | null; code: string; enabled: boolean
502	  mode?: Mode
503	  created_from?: string | null; created_at?: string; runs?: Run[]; handled?: number; note?: string
504	}
