506	/** Something a routine in "ask me" mode prepared and waits to be confirmed (GET /api/routines/proposals). */
507	export interface Proposal {
508	  id: string
509	  routine_id: string
510	  routine_name: string
511	  card_id?: string | null
512	  shipment_id?: string | null
513	  step: { do: StepKind | string; text?: string; channel?: Channel; [k: string]: unknown }
514	  preview_text?: string | null
515	  created_at?: string
516	  status: 'pending' | 'done' | 'skipped'
517	}
518	/** A routine that matches a card (GET /api/routines/would-handle). */
519	export interface WouldHandle { routine_id: string; routine_name: string; mode?: Mode; enabled: boolean }
