521	/** The trust ladder: a routine starts by asking, then tells you, then runs quietly. */
522	export const MODES: { key: Mode; label: string; hint: string; changes: string }[] = [
523	  { key: 'ask', label: 'Ask me', hint: 'Prepares each step, you send it with one tap', changes: 'Nothing leaves before you tap Send.' },
524	  { key: 'tell', label: 'Tell me', hint: 'Does it, then tells you what it did', changes: 'It acts on its own and you get a note each time.' },
525	  { key: 'quiet', label: 'Quietly', hint: 'Does it, you find it under Handled for you', changes: 'No notes; it shows up in the history only.' },
526	]
