529	/** The trigger node: what the routine looks at, in the buyer's words. */
530	export function triggerText(on?: Trigger): { title: string; text: string } {
531	  if (on === 'waiting') return { title: 'Messages still waiting for an answer', text: 'Every portal check, the emails we sent that have no reply yet' }
532	  if (on === 'replies') return { title: 'Suppliers who answered', text: 'Every portal check, the decisions a supplier has replied to' }
533	  if (on === 'shipments') return { title: 'Shipments that stopped updating', text: 'Every portal check, shipments with no new status for a while' }
534	  return { title: 'Every portal check · open decisions', text: 'New files, replies and open decisions, about every minute' }
535	}
