537	const hoursWord = (v: unknown) => {
538	  const n = Number(v)
539	  if (!Number.isFinite(n)) return String(v)
540	  return n < 1 ? `${Math.round(n * 60)} min` : `${Math.round(n * 10) / 10} h`
541	}
542	const yes = (v: unknown) => v === true || /^(yes|true|1)$/i.test(String(v))
543	
544	/**
545	 * A condition as a buyer reads it. The recipe's own text wins; the numeric and yes/no fields get
546	 * plain words when it is missing, so a field name never reaches the screen.
547	 */
548	export function condWords(c: Cond): string {
549	  if (c.text?.trim()) return c.text
550	  const more = c.op === 'gt'
551	  switch (c.field) {
552	    case 'hours_left': return `${more ? 'More' : 'Less'} than ${hoursWord(c.value)} before the deadline`
553	    case 'waiting_hours': return `No answer for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
554	    case 'silent_hours': return `No shipment update for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
555	    case 'has_reply': return yes(c.value) ? 'The supplier has answered' : 'The supplier has not answered yet'
556	    case 'reply_after_launch': return yes(c.value) ? 'The answer promises a date after launch' : 'The answer promises a date before launch'
557	    default: return `${c.op === 'contains' ? 'Mentions' : 'Is'} ${String(c.value)}`
558	  }
559	}
