566	/** POST that keeps the server's reason on failure (FastAPI puts it in `detail`). */
567	export async function call<T>(url: string, payload: unknown = {}, method = 'POST'): Promise<T> {
568	  const r = await fetch(url, {
569	    method, headers: { 'Content-Type': 'application/json' }, body: method === 'DELETE' ? undefined : JSON.stringify(payload),
570	  })
571	  if (!r.ok) {
572	    let reason = ''
573	    try { reason = String((await r.json()).detail ?? '') } catch { /* not JSON */ }
574	    throw new Error(reason || `the server answered ${r.status}`)
575	  }
576	  return r.json()
577	}
