587	  { key: 'log', label: 'Note it in the history', hint: 'A line in the case history, nobody is told', make: () => ({ id: newId('s'), do: 'log', message: 'Handled by a routine: {headline}', text: 'Note it in the history' }) },
588	  { key: 'ask_status', label: 'Ask for a status', hint: 'Emails the supplier for where the shipment is', make: () => ({ id: newId('s'), do: 'ask_status', text: 'Ask the supplier for the shipment status' }) },
