591	export function paletteKey(s: Step): string | null {
592	  if (s.do === 'log' || s.do === 'chase' || s.do === 'call' || s.do === 'ask_status') return s.do
593	  if (s.do === 'notify' && (s.channel === 'phone' || s.channel === 'teams')) return s.channel
594	  return null
