599	export type LineKind = 'send' | 'tell' | 'note' | 'chase' | 'call' | 'ask_status'
600	
601	/** One line per thing a run did (or would do, in a test run). */
602	export function didLines(run: Run, spec?: Spec | null): { kind: LineKind; channel?: Channel; text: string }[] {
603	  const out: { kind: LineKind; channel?: Channel; text: string }[] = []
604	  for (const d of run.did ?? []) {
605	    const about = d.text || d.option || ''
606	    if (d.proposed) {
607	      out.push({ kind: (d.do === 'carry_out' ? 'send' : d.do === 'notify' || d.do === 'log' ? 'tell' : d.do) as LineKind, text: `Prepared for your OK${about ? `: ${about}` : ''}` })
608	    } else if (d.do === 'carry_out') {
609	      out.push({ kind: 'send', text: `${d.dry ? 'Would send' : 'Sent'}: ${d.option ?? 'the message'}` })
610	    } else if (d.do === 'chase') {
611	      out.push({ kind: 'chase', text: `${d.dry ? 'Would chase' : 'Chased'} once in the same thread${about ? `: ${about}` : ''}` })
612	    } else if (d.do === 'call') {
613	      out.push({ kind: 'call', text: `${d.dry ? 'Would call you' : 'Called you'}${about ? `: ${about}` : ''}` })
614	    } else if (d.do === 'ask_status') {
615	      out.push({ kind: 'ask_status', text: `${d.dry ? 'Would ask' : 'Asked'} for a status${about ? `: ${about}` : ''}` })
616	    } else if (d.do === 'log') {
617	      out.push({ kind: 'note', text: `${d.dry ? 'Would note' : 'Noted'}: ${about}` })
618	    } else {
619	      out.push({ kind: 'tell', channel: d.channel, text: `${d.dry ? 'Would tell you' : 'Told you'}${where(d.channel)}: ${d.text ?? ''}` })
620	    }
621	  }
622	  // Lines from "note it" steps; the carry-out bookkeeping lines are already covered above.
623	  const sendTexts = (spec?.then ?? []).filter((s) => s.do === 'carry_out').map((s) => s.text)
624	  for (const line of run.log ?? []) {
625	    if (!line || sendTexts.some((t) => line.startsWith(t))) continue
626	    out.push({ kind: 'note', text: `${run.dry ? 'Would note' : 'Noted'}: ${line}` })
627	  }
628	  return out
629	}
