631	/** "Told you about 1 card", "Sent 2 messages", "Nothing to do" for the stats line. */
632	export function summarise(run: Run): string {
633	  if (!run.ok) return 'The last run failed'
634	  const all = run.did ?? []
635	  const asked = all.filter((d) => d.proposed).length
636	  const did = all.filter((d) => !d.proposed)
637	  const n = (k: StepKind) => did.filter((d) => d.do === k).length
638	  const sent = n('carry_out')
639	  const told = new Set(did.filter((d) => d.do === 'notify').map((d) => d.card)).size
640	  const s = (k: number) => (k === 1 ? '' : 's')
641	  const parts: string[] = []
642	  if (sent) parts.push(`sent ${sent} message${s(sent)}`)
643	  if (n('chase')) parts.push(`chased ${n('chase')} time${s(n('chase'))}`)
644	  if (n('ask_status')) parts.push(`asked for ${n('ask_status')} status${n('ask_status') === 1 ? '' : 'es'}`)
645	  if (n('call')) parts.push(`called you ${n('call') === 1 ? 'once' : `${n('call')} times`}`)
646	  if (told) parts.push(`told you about ${told} case${s(told)}`)
647	  if (asked) parts.push(`prepared ${asked} for your OK`)
648	  const out = parts.join(', ')
649	  return out ? out[0].toUpperCase() + out.slice(1) : 'Nothing to do'
650	}
651	
652	/** The last thing a real run did that may still be undone (a decision without an email). */
653	export function lastUndoable(runs?: Run[]): { id: string; text: string } | null {
654	  for (const r of runs ?? []) {
655	    if (r.dry || !r.ok) continue
656	    for (const d of [...(r.did ?? [])].reverse()) {
657	      if (d.action_id && d.do === 'carry_out' && d.status !== 'sent') return { id: d.action_id, text: d.option || d.text || 'its last step' }
658	    }
659	  }
660	  return null
661	}
662	
663	/** A sample recipe for the empty state's small diagram. */
664	export const SAMPLE: Spec = {
665	  on: 'waiting',
666	  when: [{ id: 'c1', field: 'waiting_hours', op: 'gt', value: 2, text: 'A supplier has not answered for 2 hours' }],
667	  then: [{ id: 's1', do: 'chase', text: 'Send one friendly reminder in the same thread' }],
668	}
669	import { cn } from '@/lib/utils'
670	import { ChannelIcon, StepIcon } from './RoutineFlow'
671	import { MODES, didLines, type Mode, type Run, type Spec } from './types'
672	
673	// Small parts of the routine view: the test run as plain lines, and the trust ladder as a
674	// segmented control ("Ask me · Tell me · Quietly").
675	
676	export function TestResult({ run, spec, title = "Test on today's inbox" }: { run: Run; spec?: Spec | null; title?: string }) {
677	  const lines = didLines(run, spec)
678	  return (
679	    <div>
680	      <p className="t-small text-ink-3">{title}</p>
681	      {!run.ok ? (
682	        <div className="mt-2">
683	          <p className="t-body text-late">The test failed, so this version cannot be used.</p>
684	          <pre className="t-small mt-2 max-h-32 overflow-auto whitespace-pre-wrap rounded-xl bg-soft p-3 text-ink-2">{run.error}</pre>
685	        </div>
686	      ) : lines.length === 0 ? (
687	        <p className="t-body mt-2 text-ink-2">Nothing in today's inbox matches. It waits for the next case like this.</p>
688	      ) : (
689	        <ul className="mt-2 space-y-1.5">
690	          {lines.map((l, i) => (
691	            <li key={i} className={cn('t-body flex items-start gap-2.5', run.dry ? 'text-ink' : 'text-routine')}>
692	              <span className="mt-[5px] shrink-0">
693	                {l.kind === 'send' ? <StepIcon step={{ do: 'carry_out' }} size={15} />
694	                  : l.kind === 'note' ? <StepIcon step={{ do: 'log' }} size={15} />
695	                  : l.kind === 'tell' ? <ChannelIcon channel={l.channel} size={15} />
696	                  : <StepIcon step={{ do: l.kind }} size={15} />}
697	              </span>
698	              <span className="min-w-0 break-words">{l.text}</span>
699	            </li>
700	          ))}
701	        </ul>
702	      )}
703	    </div>
704	  )
705	}
