707	/**
708	 * The trust ladder as a segmented control: Ask me, Tell me, Quietly. Each segment says in one
709	 * line what it does (on a phone only the selected one does, below the control).
710	 */
711	export function TrustControl({
712	  value, onChange, disabled, dim, note,
713	}: { value: Mode; onChange: (m: Mode) => void; disabled?: boolean; dim?: boolean; note?: string }) {
714	  const cur = MODES.find((m) => m.key === value) ?? MODES[0]
715	  return (
716	    <div className={cn('transition-opacity', dim && 'opacity-55')}>
717	      <div role="radiogroup" aria-label="How much it does on its own" className="grid grid-cols-3 gap-1 rounded-[14px] bg-soft p-1">
718	        {MODES.map((m) => {
719	          const on = value === m.key
720	          return (
721	            <button
722	              key={m.key}
723	              type="button"
724	              role="radio"
725	              aria-checked={on}
726	              disabled={disabled}
727	              onClick={() => !on && onChange(m.key)}
728	              className={cn(
729	                'min-w-0 cursor-pointer rounded-[10px] px-3 py-2 text-left transition-[background-color,box-shadow,color] duration-200 focus-visible:outline-2 focus-visible:outline-accent disabled:cursor-default',
730	                'max-sm:py-2.5 max-sm:text-center',
731	                on ? 'bg-white shadow-[0_1px_2px_rgba(24,24,26,.06),0_0_0_1px_var(--color-hair)]' : 'hover:bg-white/60',
732	              )}
733	            >
734	              <span className={cn('t-small block whitespace-nowrap font-medium', on ? 'text-ink' : 'text-ink-2')}>{m.label}</span>
735	              <span className={cn('t-small hidden leading-snug sm:block', on ? 'text-ink-2' : 'text-ink-3')}>{m.hint}</span>
736	            </button>
737	          )
738	        })}
739	      </div>
740	      <p className="t-small mt-2 text-ink-3" aria-live="polite">
741	        <span className="sm:hidden">{cur.hint}. </span>{note ?? cur.changes}
742	      </p>
743	    </div>
744	  )
745	}
746	import { BellRing, MailWarning, MessageSquare, NotebookPen, PackageSearch, Phone, Send, Smartphone } from 'lucide-react'
747	import type { Channel, Step } from './types'
748	
749	// Step icons and the before/after merge the routine diagram (FlowGraph) uses to show what a
750	// change does, node by node.
751	
752	export type Mark = 'same' | 'added' | 'removed' | 'changed'
753	export interface Row<T> { item: T; mark: Mark; old?: T; moved?: boolean }
754	
755	/** Before and after merged by block id, removed blocks kept at their old place. */
756	export function merge<T extends { id: string; text: string }>(after: T[], before?: T[]): Row<T>[] {
757	  if (!before) return after.map((item) => ({ item, mark: 'same' }))
758	  const old = new Map(before.map((b) => [b.id, b]))
759	  const now = new Set(after.map((a) => a.id))
760	  const commonBefore = before.filter((b) => now.has(b.id)).map((b) => b.id)
761	  const commonAfter = after.filter((a) => old.has(a.id)).map((a) => a.id)
762	  // Removed blocks hang after the last surviving block that preceded them.
763	  const anchored = new Map<string | null, T[]>()
764	  let anchor: string | null = null
765	  for (const b of before) {
766	    if (now.has(b.id)) { anchor = b.id; continue }
767	    anchored.set(anchor, [...(anchored.get(anchor) ?? []), b])
768	  }
769	  const gone = (key: string | null) => (anchored.get(key) ?? []).map((item): Row<T> => ({ item, mark: 'removed' }))
770	  const rows: Row<T>[] = gone(null)
771	  for (const a of after) {
772	    const b = old.get(a.id)
773	    const mark: Mark = !b ? 'added' : JSON.stringify(b) === JSON.stringify(a) ? 'same' : 'changed'
774	    const moved = !!b && commonBefore.indexOf(a.id) !== commonAfter.indexOf(a.id)
775	    rows.push({ item: a, mark, old: b, moved })
776	    rows.push(...gone(a.id))
777	  }
778	  return rows
779	}
780	
781	export function StepIcon({ step, size = 16, className }: { step: Pick<Step, 'do' | 'channel'>; size?: number; className?: string }) {
782	  const c = className ?? 'text-ink-3'
783	  if (step.do === 'carry_out') return <Send size={size} strokeWidth={1.75} className={c} />
784	  if (step.do === 'log') return <NotebookPen size={size} strokeWidth={1.75} className={c} />
785	  if (step.do === 'chase') return <MailWarning size={size} strokeWidth={1.75} className={c} />
786	  if (step.do === 'ask_status') return <PackageSearch size={size} strokeWidth={1.75} className={c} />
787	  if (step.do === 'call') return <Phone size={size} strokeWidth={1.75} className={c} />
788	  return <ChannelIcon channel={step.channel} size={size} className={className} />
789	}
790	
791	export function ChannelIcon({ channel, size = 16, className = 'text-ink-3' }: { channel?: Channel; size?: number; className?: string }) {
792	  if (channel === 'phone') return <Smartphone size={size} strokeWidth={1.75} className={className} />
793	  if (channel === 'teams') return <MessageSquare size={size} strokeWidth={1.75} className={className} />
794	  return <BellRing size={size} strokeWidth={1.75} className={className} />
795	}
