FLAG_FIELDS = {"has_reply", "reply_after_launch"}
FIELDS = TEXT_FIELDS | NUM_FIELDS | FLAG_FIELDS
OPS = {"contains", "is", "any_of", "lt", "gt"}
STEPS = {"carry_out", "notify", "log", "chase", "call", "ask_status"}
CHANNELS = {"phone", "teams", "both"}
